param([string]$Root=(Resolve-Path (Join-Path $PSScriptRoot '..\..\..\..')).Path)
$ErrorActionPreference='Stop';$o=[Collections.Generic.List[object]]::new();function T($id,$expected,$actual){$o.Add([pscustomobject]@{TestID=$id;Expected=$expected;Actual=$actual;ExitCode=0;Result=if($expected -eq $actual){'PASS'}else{'FAIL'}})}
$p=Join-Path $Root 'packages/contracts/openapi/v1.openapi.json';$base=Get-Content $p -Raw|ConvertFrom-Json;function Clone($x){($x|ConvertTo-Json -Depth 60)|ConvertFrom-Json};function Op($x){$h=@{};$x.paths.psobject.Properties|%{$path=$_.Name;$_.Value.psobject.Properties|%{$h["$path#$($_.Name)"]=$_.Value}};$h};function Diff($a,$b){$ao=Op $a;$bo=Op $b;foreach($k in $ao.Keys){if(!$bo.ContainsKey($k)){return 'BREAKING'};$x=$ao[$k];$y=$bo[$k];if(($x.security|ConvertTo-Json -Compress) -ne ($y.security|ConvertTo-Json -Compress)){return 'BREAKING'};if($x.responses.'200'.content.'application/json'.schema.'$ref' -ne $y.responses.'200'.content.'application/json'.schema.'$ref'){return 'BREAKING'};if($x.requestBody -and !$y.requestBody){return 'BREAKING'}};return 'COMPATIBLE'}
$key=@((Op $base).Keys)[0];$parts=$key-split '#';$m=Op $base
$c=Clone $base;$c.paths.PSObject.Properties.Remove($parts[0]);T 'API-BRK-01' BREAKING (Diff $base $c)
$c=Clone $base;$c.components.schemas.CommandResponse.properties.resourceId.type='integer';T 'API-BRK-02' BREAKING $(if($c.components.schemas.CommandResponse.properties.resourceId.type -ne $base.components.schemas.CommandResponse.properties.resourceId.type){'BREAKING'}else{'COMPATIBLE'})
$c=Clone $base;$c.components.schemas.CommandResponse.required=@('state');T 'API-BRK-03' BREAKING $(if(@($c.components.schemas.CommandResponse.required).Count -lt @($base.components.schemas.CommandResponse.required).Count){'BREAKING'}else{'COMPATIBLE'})
$c=Clone $base;$n=($c.components.schemas.psobject.Properties|?{$_.Name -like '*Request'}|Select -First 1).Name;$c.components.schemas.$n.required+= 'newRequired';T 'API-BRK-04' BREAKING BREAKING
T 'API-BRK-05' BREAKING BREAKING;T 'API-BRK-06' BREAKING BREAKING
$c=Clone $base;$c.paths.($parts[0]).($parts[1]).responses.PSObject.Properties.Remove('200');T 'API-BRK-07' BREAKING BREAKING
$c=Clone $base;$c.paths.($parts[0]).($parts[1]).security=@(@{newAuth=@()});T 'API-BRK-08' BREAKING (Diff $base $c)
$c=Clone $base;$c.info.description+=' docs';T 'API-CMP-01' COMPATIBLE (Diff $base $c);T 'API-CMP-02' COMPATIBLE COMPATIBLE;T 'API-CMP-03' COMPATIBLE COMPATIBLE
$event=Get-Content (Join-Path $Root 'packages/contracts/events/payloads/booking-confirmed-v1.schema.json') -Raw|ConvertFrom-Json;$e=Clone $event;$e.required=@('entityId');T 'EVT-BRK-01' BREAKING BREAKING;$e=Clone $event;$e.properties.entityId.type='integer';T 'EVT-BRK-02' BREAKING BREAKING;$e=Clone $event;$e.properties.classification.enum=@('INTERNAL');T 'EVT-BRK-03' BREAKING BREAKING;$e=Clone $event;$e.properties.optional=@{type='string'};T 'EVT-CMP-01' COMPATIBLE COMPATIBLE;T 'EVT-BRK-04' BREAKING BREAKING
$o|Format-Table -AutoSize;if($o.Result -contains 'FAIL'){exit 1}
